argv:
$ErrorActionPreference='Stop'
$userHome=$env:USERPROFILE
$roots=@(
  (Join-Path $userHome 'Downloads'),
  (Join-Path $userHome 'Pictures'),
  (Join-Path $userHome 'Desktop')
)
$recent=@()
foreach($root in $roots){
  if(Test-Path -LiteralPath $root){
    Get-ChildItem -LiteralPath $root -File -Recurse -ErrorAction SilentlyContinue |
      Where-Object {$_.LastWriteTime -gt (Get-Date).AddMinutes(-15)} |
      Sort-Object LastWriteTime -Descending |
      Select-Object -First 30 |
      ForEach-Object {
        $recent += [pscustomobject]@{name=$_.Name;path=$_.FullName;ext=$_.Extension;bytes=$_.Length;last_write=[string]$_.LastWriteTime}
      }
  }
}
Add-Type @"
using System;
using System.Text;
using System.Runtime.InteropServices;
public static class W32Enum2 {
  public delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);
  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumWindowsProc lpEnumFunc, IntPtr lParam);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetWindowText(IntPtr hWnd, StringBuilder lpString, int nMaxCount);
  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr hWnd);
}
"@
$wins=New-Object System.Collections.ArrayList
$cb=[W32Enum2+EnumWindowsProc]{
 param($h,$l)
 if([W32Enum2]::IsWindowVisible($h)){
   $sb=New-Object System.Text.StringBuilder 512
   [void][W32Enum2]::GetWindowText($h,$sb,$sb.Capacity)
   $t=$sb.ToString().Trim()
   if($t){[void]$wins.Add([pscustomobject]@{hwnd=[string]$h;title=$t})}
 }
 return $true
}
[W32Enum2]::EnumWindows($cb,[IntPtr]::Zero)|Out-Null
[pscustomobject]@{recent=$recent;windows=$wins}|ConvertTo-Json -Depth 6 -Compress
